<script setup>
import {computed,shallowRef} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {path} from '../data'
import Icon from '../components/Icon.vue'
import Strategy from './Strategy.vue'
import QuantFundCard from '../components/quant/QuantFundCard.vue'
import QuantFundDetail from '../components/quant/QuantFundDetail.vue'
import QuantFundPositions from '../components/quant/QuantFundPositions.vue'
import QuantFundInterestRecords from '../components/quant/QuantFundInterestRecords.vue'
import QuantAmbient from '../components/quant/QuantAmbient.vue'
import RequestState from '../components/ui/RequestState.vue'
import Skeleton from '../components/ui/Skeleton.vue'
import BackLink from '../components/ui/BackLink.vue'
import {getQuantFund,getQuantFundOrder,listQuantFunds} from '../api/quantFund.js'
import {useRequest} from '../composables/useRequest.js'
import NotFound from './NotFound.vue'
import '../styles/quant-fidelity.css'
const route=useRoute(),router=useRouter(),market=shallowRef('all')
const productId=computed(()=>route.params.productId||''),orderId=computed(()=>route.params.orderId||''),section=computed(()=>route.params.recordId?'strategy':productId.value||orderId.value?'quant-fund':route.params.section),mine=computed(()=>['mine','positions'].includes(route.params.id)),isFund=computed(()=>section.value==='quant-fund')
// The routed product or order is loaded here: an unknown id renders the not-found page, and the loaded record is
// passed down so the detail views never render against a missing entity.
const entity=useRequest(()=>productId.value?getQuantFund(productId.value):orderId.value?getQuantFundOrder(orderId.value):Promise.resolve(null),{key:()=>productId.value+'|'+orderId.value,tags:['quantFund']})
// Catalogue: the fund list and the detail page's "more products"; not requested on strategy or interest-record pages.
const wantsCatalog=computed(()=>isFund.value&&!orderId.value)
const catalog=useRequest(()=>wantsCatalog.value?listQuantFunds():Promise.resolve([]),{key:wantsCatalog,tags:['quantFund']})
// Unknown product/order ids and mismatched section/id pairs render the not-found page.
const missing=computed(()=>{const id=route.params.id;if(productId.value||orderId.value)return entity.status.value==='error'&&entity.error.value?.code==='notFound';return Boolean(id)&&!((section.value==='strategy'&&id==='mine')||(section.value==='quant-fund'&&id==='positions'))})
const quantFunds=computed(()=>catalog.data.value||[])
const assets=computed(()=>[...new Set(quantFunds.value.map(p=>p.asset))].sort())
const funds=computed(()=>market.value==='all'?quantFunds.value:quantFunds.value.filter(p=>p.asset===market.value))
function openFund(product){router.push(path(`/ai-quant/quant-fund/products/${product.id}`))}
</script>
<template><NotFound v-if="missing"/><Strategy v-else-if="section==='strategy'"/><div v-else class="page-wrap quant-page" :class="section?'quant-sub':'quant-landing'"><QuantAmbient :aurora="isFund&&!productId&&!orderId"/>
<template v-if="!section"><div class="page-hero"><small class="page-kicker">{{ $t("aiQuant.landing.eyebrow") }}</small><h1 class="page-title">{{ $t("aiQuant.landing.title") }}</h1><p class="page-desc">{{ $t("aiQuant.landing.subtitle") }}</p></div><div class="two-cols quant-intro"><div v-for="(kind,i) in [&quot;aiQuant.landing.strategy.name&quot;,&quot;aiQuant.landing.quantFund.name&quot;]" :key="kind" class="card nt-glow-host"><span class="nt-glow glow-quant-channel" :class="{green:i}" aria-hidden="true"></span><div class="coin-label"><Icon :name="i?'shield':'bot'" green/><div><small class="page-kicker">{{ $t(i?"aiQuant.landing.quantFund.kicker":"aiQuant.landing.strategy.kicker") }}</small><h2>{{ $t(kind) }}</h2></div></div><p>{{ $t(i?"aiQuant.landing.quantFund.valueProp":"aiQuant.landing.strategy.valueProp") }}</p><div class="quant-chips"><span class="tag-chip">{{ $t(i?"aiQuant.landing.quantFund.chipA":"aiQuant.landing.strategy.chipA") }}</span> <span class="tag-chip">{{ $t(i?"aiQuant.landing.quantFund.chipB":"aiQuant.landing.strategy.chipB") }}</span></div><RouterLink class="pill primary" :to="path(i?'/ai-quant/quant-fund':'/ai-quant/strategy')">{{ $t(i?"aiQuant.landing.quantFund.browse":"aiQuant.landing.strategy.browse") }} <Icon name="arrow-right"/></RouterLink><RouterLink class="card-footer" :to="path(i?'/ai-quant/quant-fund/positions':'/ai-quant/strategy/mine')"><span>{{ $t(i?"aiQuant.landing.quantFund.mine":"aiQuant.landing.strategy.mine") }}</span><small>{{ $t("quant.ui.private") }}{{ $t(i?"quant.ui.subscriptionsAndInterest":"quant.ui.runningInstances") }}</small></RouterLink></div></div></template>
<RequestState v-else-if="orderId&&entity.status.value==='error'" :status="entity.status.value" :error="entity.error.value" class="qf-panel qf-request-frame" @retry="entity.refresh"/><QuantFundInterestRecords v-else-if="orderId" :order="entity.data.value"/><template v-else><nav class="subnav"><RouterLink :to="path(isFund?'/ai-quant/quant-fund':'/ai-quant/strategy')" :class="{active:Boolean(productId)}"><Icon :name="isFund?'shield':'bot'"/>{{ $t(isFund?"aiQuant.landing.quantFund.name":"aiQuant.nav.strategy") }}</RouterLink><RouterLink :to="path(isFund?'/ai-quant/quant-fund/positions':'/ai-quant/strategy/mine')"><Icon name="briefcase"/>{{ $t(isFund?"aiQuant.landing.quantFund.mine":"aiQuant.landing.strategy.mine") }}</RouterLink></nav>
<QuantFundPositions v-if="mine"/><RequestState v-else-if="productId" :status="entity.status.value" :error="entity.error.value" class="qf-panel qf-request-frame" @retry="entity.refresh"><template #loading><div class="qf-detail-page"><BackLink :to="path('/ai-quant/quant-fund')" class="qf-back">{{ $t('aiQuant.quantFund.title') }}</BackLink><div class="qf-detail"><div class="qf-detail-grid"><div class="qf-detail-main">
 <section class="qf-panel qf-skeleton-panel qf-skeleton-hero"><Skeleton width="160px" height="22px"/><Skeleton width="70%" height="40px"/><Skeleton width="90%"/><Skeleton width="60%"/><div class="qf-skeleton-tags"><Skeleton width="80px" height="24px"/><Skeleton width="80px" height="24px"/></div></section>
 <section class="qf-panel qf-skeleton-panel qf-skeleton-calc"><h2 class="qf-panel-title"><Icon name="calculator"/>{{ $t('aiQuant.quantFund.detail.calcTitle') }}</h2><Skeleton height="72px"/><Skeleton height="96px"/><Skeleton width="80%" height="12px"/></section>
 <section class="qf-panel qf-skeleton-panel qf-skeleton-flow"><h2 class="qf-panel-title"><Icon name="route"/>{{ $t('aiQuant.quantFund.detail.flowTitle') }}</h2><Skeleton v-for="n in 4" :key="n" width="70%" height="18px"/></section>
 <section class="qf-panel qf-skeleton-panel qf-skeleton-quota"><h2 class="qf-panel-title"><Icon name="shield"/>{{ $t('aiQuant.quantFund.detail.quotaTitle') }}</h2><Skeleton height="64px"/><Skeleton height="6px"/><Skeleton width="100%" height="14px"/></section>
</div><aside class="qf-panel qf-detail-aside qf-skeleton-panel qf-skeleton-aside"><Skeleton height="64px"/><Skeleton width="80px" height="12px"/><Skeleton width="150px" height="44px"/><Skeleton height="6px"/><Skeleton width="100%" height="14px"/><Skeleton height="48px" class="qf-skeleton-cta"/></aside></div></div></div></template><QuantFundDetail :product="entity.data.value" :catalog="quantFunds"/></RequestState>
<template v-else-if="isFund"><div class="qf-list">
<section class="qf-hero"><div class="qf-hero-glow" aria-hidden="true"></div><div class="qf-hero-copy"><span class="qf-hero-eyebrow"><Icon name="sparkles" green/>{{ $t("aiQuant.quantFund.hero.subtitle") }}</span><h1>{{ $t("aiQuant.quantFund.hero.title") }}</h1><p>{{ $t("aiQuant.quantFund.hero.description") }}</p></div>
<div class="qf-hero-mark" aria-hidden="true"><div class="qf-hero-mark-glow"></div><div class="qf-hero-ring"></div><div class="qf-hero-ring dashed"></div><div class="qf-hero-core"><Icon name="bot" green/></div><div class="qf-hero-badge bottom"><Icon name="shield"/></div><div class="qf-hero-badge top"><Icon name="trending-up-down" green/></div></div></section>
<section class="qf-catalog"><div v-if="catalog.status.value==='loading'" class="qf-filters" aria-hidden="true"><Skeleton width="72px" height="26px"/><Skeleton width="56px" height="26px"/></div><div v-if="assets.length" class="qf-filters" role="group" :aria-label="$t('aiQuant.quantFund.filters.assetAll')"><button type="button" :aria-pressed="market==='all'" :class="{active:market==='all'}" @click="market='all'">{{ $t("aiQuant.quantFund.filters.assetAll") }}</button><button v-for="asset in assets" :key="asset" type="button" :aria-pressed="market===asset" :class="{active:market===asset}" @click="market=asset">{{ asset }}</button></div>
<RequestState :status="catalog.status.value" :error="catalog.error.value" class="qf-panel qf-request-frame" @retry="catalog.refresh"><template #loading><div class="three-cols qf-grid"><div v-for="n in 6" :key="n" class="qf-card qf-skeleton-card"><div class="qf-card-head"><div class="qf-card-title"><Skeleton width="32px" height="32px" round/><div class="qf-skeleton-lines"><Skeleton width="180px" height="18px"/><Skeleton width="48px" height="12px"/></div></div><Skeleton width="56px" height="22px"/></div><div class="qf-card-rate"><div class="qf-skeleton-lines"><Skeleton width="80px" height="12px"/><Skeleton width="110px" height="30px"/></div><div class="qf-skeleton-lines"><Skeleton width="56px" height="12px"/><Skeleton width="48px" height="18px"/></div></div><div class="qf-skeleton-lines qf-skeleton-limit"><Skeleton width="140px" height="12px"/><Skeleton width="200px" height="18px"/></div><div class="qf-skeleton-lines qf-skeleton-progress"><Skeleton height="6px"/><Skeleton width="100%" height="14px"/></div><div class="qf-skeleton-tags"><Skeleton width="72px" height="24px"/><Skeleton width="72px" height="24px"/></div><Skeleton height="44px" class="qf-skeleton-cta"/></div></div></template><div class="three-cols qf-grid"><QuantFundCard v-for="f in funds" :key="f.id" :product="f" @open="openFund"/></div></RequestState></section>
<footer class="qf-disclaimer"><Icon name="shield"/><span>{{ $t("aiQuant.quantFund.hero.disclaimer") }}</span></footer>
</div></template>

</template></div></template>
<style>.qf-skeleton-panel{display:grid;gap:14px;align-content:start}.qf-skeleton-lines{display:grid;gap:8px;min-width:0}.qf-skeleton-card .qf-card-head{height:62px;align-items:flex-start}.qf-skeleton-card .qf-card-rate{height:52px;align-items:flex-end}.qf-skeleton-limit{height:42px;align-content:center}.qf-skeleton-progress{height:32px;align-content:space-between;gap:0}.qf-skeleton-tags{display:flex;gap:8px;height:24px}.qf-skeleton-cta{border-radius:999px}.qf-skeleton-hero,.qf-skeleton-calc,.qf-skeleton-flow,.qf-skeleton-quota,.qf-skeleton-aside{overflow:hidden;box-sizing:border-box}.qf-skeleton-hero{height:244px}.qf-skeleton-calc{height:341px}.qf-skeleton-flow{height:204px;gap:12px}.qf-skeleton-quota{height:208px}.qf-skeleton-aside{height:314px;gap:12px;align-content:space-between}.qf-request-frame.nt-request-error{margin-top:16px}</style>
<style scoped>.strategy-hero{padding:40px 0;gap:10%}.strategy-hero h1{font-size:3.5rem}.strategy-graph{align-self:center;height:380px}.strategy-graph .eyebrow{margin:0}.fund-hero{padding:56px 40px;margin-top:60px}.fund-hero .page-desc{max-width:600px}#templates{scroll-margin-top:90px}@media(max-width:900px){.strategy-hero h1{font-size:2.5rem}.strategy-hero{gap:24px}.strategy-graph{height:300px}.fund-hero{padding:32px;margin-top:30px}}@media(max-width:600px){.strategy-hero h1{font-size:2.25rem}.strategy-hero .two-cols{grid-template-columns:1fr 1fr}.strategy-graph{min-height:260px}.fund-hero{padding:24px}.fund-hero .page-title{font-size:1.75rem}}
</style>
